    s = front(s, '1.4', 'CH-54: DS-09 آستانه به دقیقه، کاربران فروشگاه و چهار دسته مجوز، اشتراک؛ VL-13 (DEC-309، DEC-310، DEC-316، DEC-317)')
    s = R(s, '| ‏آستانه اعتبار موجودی | ‏ساعت، ۱ تا ۷۲۰؛ **بدون پیش‌فرض** | ‏مالک، یا ادمین دارای مجوز «تغییر آستانه» | ‏PRD-03e؛ DEC-259؛ DEC-83 |',
          '| ‏آستانه اعتبار موجودی | ‏دقیقه، ۱۵ تا ۶۰؛ **بدون پیش‌فرض** | ‏مدیر، یا کارمند با مجوز «تنظیمات» | ‏PRD-03e؛ DEC-310؛ DEC-316 |')
    s = R(s, '| ‏مجوزهای اعطاشده | ‏برای هر ادمین: «اصلاح منبع» بله / خیر · «تغییر آستانه» بله / خیر | ‏فقط مالک | ‏PRD-03e؛ DEC-113؛ DEC-259 |',
          '| ‏کاربران فروشگاه | ‏برای هر حساب: نام، نام خانوادگی، نام کاربری (یکتا)، نقش (VL-13: مدیر / کارمند)، حساب فعال / غیرفعال، رمز موقت بله / خیر | ‏مدیر برای کارمندان؛ حساب مدیر با تیم محصول | ‏DEC-316؛ DEC-317؛ ENV-31 |\n| ‏مجوزهای اعطاشده | ‏برای هر کارمند و هر دسته VL-14: «ویرایش» / «فقط دیدن»، با آخرین عامل و زمان تغییر **همان مجوز** | ‏فقط مدیر | ‏PRD-03e؛ DEC-316 (جایگزین DEC-113، DEC-259) |\n| ‏اشتراک | ‏نوع (ماهانه)، تاریخ پایان؛ روزهای باقی‌مانده محاسبه می‌شود | ‏تیم محصول؛ مدیر فقط می‌بیند | ‏DEC-309؛ A-29 |')
    s = R(s, '| ‏VL-12 | ‏نشانه بازبینی |', '| ‏VL-13 | ‏نقش در پنل فروشگاه | ‏مدیر · کارمند | ‏DEC-316 |\n| ‏VL-14 | ‏دسته مجوز | ‏«بررسی موجودی» · «محصولات و گونه‌ها» · «دانشنامه فروشگاه» · «تنظیمات» | ‏DEC-316 |\n| ‏VL-12 | ‏نشانه بازبینی |')
    return hist(s, '1.4', 'DS-09: آستانه به دقیقه ۱۵ تا ۶۰؛ «کاربران فروشگاه»، مجوز برای هر دسته با آخرین تغییر، «اشتراک»؛ VL-13 و VL-14 تازه (DEC-309، DEC-310، DEC-316، DEC-317)')

