    s = R(s, 'گونه با تأیید ۳۰ ساعت پیش؛ آستانه آزمون ۲۴ ساعت', 'گونه با تأیید ۹۰ دقیقه پیش؛ آستانه آزمون ۶۰ دقیقه')
