    s = R(s, '‏حداکثر ساعتی که از زمان تأیید می‌تواند بگذرد (۱ تا ۷۲۰، بدون پیش‌فرض؛ مقدار آزمون ۲۴ ساعت)؛ مالک فروشگاه، یا ادمین دارای مجوز «تغییر آستانه اعتبار»، تنظیم می‌کند', '‏حداکثر دقیقه‌ای که از زمان تأیید می‌تواند بگذرد (۱۵ تا ۶۰، بدون پیش‌فرض؛ مقدار آزمون ۶۰ دقیقه)؛ مدیر فروشگاه، یا کارمند با مجوز «تنظیمات»، تنظیم می‌کند')
    s = R(s, '| ‏DEC-83؛ DEC-259؛ DEC-262؛ D-02 |', '| ‏DEC-83؛ DEC-310؛ DEC-316؛ D-02 |')
    s = R(s, '| ‏دانش و سیاست | ‏Knowledge & policy | ‏متن‌های تأییدشده فروشگاه مثل ارسال، مرجوعی، راهنمای سایز (DS-03) | ‏— | ‏DS-03 |', '| ‏دانش و سیاست | ‏Knowledge & policy | ‏متن‌های تأییدشده فروشگاه مثل ارسال، مرجوعی، راهنمای سایز (DS-03) | ‏**در رابط: «دانشنامه فروشگاه»** (DEC-315) | ‏DS-03 |')
    s = R(s, '| ‏تنظیمات فروشگاه | ‏Store settings | ‏آستانه اعتبار، ساعات کاری، زمان پاسخ، مسیر تماس جایگزین، منطقه زمانی؛ فقط مالک | ‏— | ‏DS-09؛ DEC-146 |', '| ‏تنظیمات فروشگاه | ‏Store settings | ‏اشتراک (فقط مدیر)، آستانه اعتبار، ساعات کاری، زمان پاسخ، مسیر تماس جایگزین، منطقه زمانی؛ ویرایش: مدیر یا کارمند با مجوز «تنظیمات» | ‏— | ‏DS-09؛ DEC-146؛ DEC-309؛ DEC-316 |')
