def bump(path):
    s = open(path, encoding='utf-8').read(); v = re.search(r'^version: (\d+)\.(\d+)', s, flags=re.M)
    return f'{v.group(1)}.{int(v.group(2)) + 1}'
for name, fn in [('PRD-04-EP02 - Inventory Validity.md', ep02), ('PRD-04-EP05 - Reference Data Management.md', ep05), ('PRD-04-EP06 - Measurement & Audit.md', ep06),
                 ('PRD-04-DD - Data Dictionary.md', dd), ("PRD-04-00 - Product-wide Rules & Don'ts.md", r0400), ('PRD-05c - Store Management Panel.md', c05),
                 ('PRD-05 - UX Flows.md', p05), ('PRD-07 - Environment & System Requirements.md', p07), ('PRD-08 - Assumptions, Constraints & Risks.md', p08),
                 ('PRD-09 - Dependencies.md', p09), ('PRD-04 - Features.md', p04), ('PRD-11a - Execution Plan.md', p11a), ('PRD-11b - Acceptance.md', p11b),
                 ('PRD-12 - Future Release Plan.md', p12), ('PRD-15 - Glossary.md', gl)]:
    path = S + name; nv = bump(path)
    def wrap(s, fn=fn, nv=nv):
        t = fn(s)
        return t.replace('version: BUMP', f'version: {nv}').replace(' · BUMP — ', f' · {nv} — ').replace('| ‏BUMP |', f'| ‏{nv} |')
    rw(path, wrap)
